contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 _unused) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= 0);

        address caller = address(this);
        uint256 balBefore = c.balances(caller); if (__ESBMC_reverted()) return;
        uint256 cBalanceBefore = address(c).balance;

        require(balBefore == 0);

        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 balAfter = c.balances(caller); if (__ESBMC_reverted()) return;
        uint256 cBalanceAfter = address(c).balance;

        assert(!reverted && balAfter == 0 && cBalanceAfter == cBalanceBefore);
    }

    receive() external payable {}
}

