        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= 0);
        address caller = address(this);
        uint256 balBefore;
        try c.balances(caller) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint256 cBalanceBefore = address(c).balance;
        vm.assume(balBefore == 0);
        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 balAfter;
        try c.balances(caller) returns (uint256 __r) { balAfter = __r; } catch { return; }
        uint256 cBalanceAfter = address(c).balance;
        assertTrue(!reverted && balAfter == 0 && cBalanceAfter == cBalanceBefore);
